package org.sleepwell.app;
import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.time.*;import java.util.*;import java.util.function.BooleanSupplier;
/** Public custom-MIME contract v1: root sleep_summary_format=1, window, totals, records.
 * records contain only ordinal, UTC reviewed bounds, end date, known zone/null, source/origin/sensor,
 * reviewed duration and edited/interrupted/clock_changed flags. No DB IDs or raw private payloads.
 * Window selects closed periods by effective end date in the explicitly exported selection zone.
 * This describes app-reviewed coverage, not validated sleep/health data or an importable backup. */
final class SleepSummary {
 static final class Row {final String date,source;final long duration;Row(String date,String source,long duration){this.date=date;this.source=source;this.duration=duration;}}
 static final class Data {final byte[] bytes;final List<Row> rows;final int days,rejected;final LocalDate from,through;final String zone;final long total,unique;Data(byte[] bytes,List<Row> rows,int days,int rejected,LocalDate from,LocalDate through,String zone,long total,long unique){this.bytes=bytes;this.rows=List.copyOf(rows);this.days=days;this.rejected=rejected;this.from=from;this.through=through;this.zone=zone;this.total=total;this.unique=unique;}}
 static Data read(Store store,int days,long now,ZoneId zone,BooleanSupplier active)throws Exception{if(days!=7&&days!=30)throw new IllegalArgumentException("Choose 7 or 30 days.");LocalDate through=Instant.ofEpochMilli(now).atZone(zone).toLocalDate(),from=through.minusDays(days-1);SQLiteDatabase db=store.getReadableDatabase();db.beginTransactionNonExclusive();try{List<org.json.JSONObject> ids=store.rows("SELECT id FROM sessions WHERE end IS NOT NULL ORDER BY end DESC LIMIT 3001");if(ids.size()>3000)throw new IllegalStateException("This history exceeds the bounded 3,000-record summary scan. Your data is kept.");JSONArray records=new JSONArray();List<Row> rows=new ArrayList<>();List<RecordIntervals.Span> coverage=new ArrayList<>();int rejected=0;long total=0;for(JSONObject item:ids){if(!active.getAsBoolean())throw new java.io.IOException("Summary preparation cancelled.");RecordEntry record;try{record=Records.get(store,item.optLong("id"));}catch(RuntimeException unreadable){throw new IllegalStateException("A saved record could not be read. No partial summary was prepared.");}if(record.edit.start<=0||record.edit.end<=record.edit.start||record.edit.end>now||record.edit.end-record.edit.start>SensorProvenance.MAX_SESSION){if(record.rawEnd>0&&record.rawEnd<=now){LocalDate invalidDate=Instant.ofEpochMilli(record.rawEnd).atZone(zone).toLocalDate();if(!invalidDate.isBefore(from)&&!invalidDate.isAfter(through))rejected++;}continue;}LocalDate date=Instant.ofEpochMilli(record.edit.end).atZone(zone).toLocalDate();if(date.isBefore(from)||date.isAfter(through))continue;if(rows.size()>=1000)throw new IllegalStateException("More than 1,000 periods are selected. Choose a shorter summary window.");String source=!record.healthConnect.isEmpty()?"provider_import":record.manual()?"user_reported":record.source.equals("tracked")?"tracked":record.source.equals("legacy")?"legacy_timing":"unknown",origin=Set.of("local","imported","legacy").contains(record.origin)?record.origin:"unknown",sensor=record.sonar()?"contactless_echo_change":record.sensor.equals(SensorProvenance.MOTION)?"phone_accelerometer":record.manual()?"none":"unknown";long duration=record.duration();if(duration<0||duration>record.edit.end-record.edit.start)throw new IllegalStateException("A reviewed duration could not be represented. No partial summary was prepared.");String knownZone=null;try{if(!record.zone.isEmpty())knownZone=ZoneId.of(record.zone).getId();}catch(DateTimeException unknown){}records.put(new JSONObject().put("ordinal",rows.size()+1).put("start_utc",Instant.ofEpochMilli(record.edit.start).toString()).put("end_utc",Instant.ofEpochMilli(record.edit.end).toString()).put("end_date",date.toString()).put("recorded_zone",knownZone==null?JSONObject.NULL:knownZone).put("source",source).put("origin",origin).put("sensor",sensor).put("reviewed_duration_ms",duration).put("edited",record.edited).put("interrupted",record.interrupted!=0).put("clock_changed",record.clockChanged!=0));rows.add(new Row(date.toString(),source,duration));coverage.addAll(record.coverage());if(coverage.size()>50000)throw new IllegalStateException("Too many reviewed intervals for this summary. Choose a shorter window.");total=Math.addExact(total,duration);}long unique=RecordIntervals.length(coverage);JSONObject root=new JSONObject().put("sleep_summary_format",1).put("mime",SleepSummaryFileProvider.MIME).put("window",new JSONObject().put("days",days).put("from_date",from.toString()).put("through_date",through.toString()).put("selection_zone",zone.getId()).put("selection","Closed periods whose edited end falls in this local date range; full reviewed periods are included." )).put("totals",new JSONObject().put("periods",rows.size()).put("sum_reviewed_duration_ms",total).put("unique_reviewed_coverage_ms",unique).put("rejected_invalid_closed_records",rejected)).put("records",records).put("method","Duration is app-reviewed coverage after pauses, explicit awake edits and accepted awake estimates/provider awake intervals. Unmarked awake time may remain. Legacy timing may lack measured active coverage. Period durations may overlap; unique reviewed coverage counts overlaps once. Missing periods are absent, never zero-filled. Not validated sleep stages or health data.").put("excluded","Private diary, notes, tags, ratings, audio, detailed sound labels, raw sensors, device/provider IDs, credentials and sensor configurations.");byte[] bytes=root.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);if(bytes.length>SleepSummaryFiles.MAX_BYTES)throw new IllegalStateException("This summary exceeds 1 MiB. Choose a shorter window.");if(!active.getAsBoolean())throw new java.io.IOException("Summary preparation cancelled.");db.setTransactionSuccessful();return new Data(bytes,rows,days,rejected,from,through,zone.getId(),total,unique);}finally{db.endTransaction();}}
 private SleepSummary(){}
}
